import React, { useState, useEffect } from 'react';
import axios from 'export'; // (Note: ඔයාගේ ඇප් එකේ තියෙන සාමාන්‍ය 'axios' පුස්තකාලය)
import axiosDirect from 'axios';

export default function StudentDashboard({ name, userName, userUsername, username, grade, subjects, handleLogout }) {
  const [materials, setMaterials] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  
  // 🟢 NEW: දැනට බලන PDF/Video නිබන්ධනය තබා ගන්නා ප්‍රදර්ශක State එක
  const [previewMaterial, setPreviewMaterial] = useState(null);

  // සැබෑ ලොගින් දත්ත හඳුනාගැනීම (Props Fallbacks)
  const loggedInUsername = username || userUsername || '';
  const loggedInName = name || userName || '';

  // ඩේටාබේස් එකෙන් කෙලින්ම ඇදගන්නා ශිෂ්‍ය තොරතුරු State එක
  const [liveProfile, setLiveProfile] = useState(null);

  useEffect(() => {
    // ඩේටාබේස් එකේ Enrolled වෙලා තියෙන ඇත්තම සබ්ජෙක්ට්ස් ටික ලයිව්ම කියවීම
    axiosDirect.get('http://localhost:8082/api/view-students')
      .then(res => {
        if (Array.isArray(res.data)) {
          const currentStudent = res.data.find(s => 
            (s.username && loggedInUsername && String(s.username).toLowerCase() === String(loggedInUsername).toLowerCase()) ||
            (s.name && loggedInName && String(s.name).toLowerCase() === String(loggedInName).toLowerCase())
          );
          if (currentStudent) {
            setLiveProfile(currentStudent);
          }
        }
      })
      .catch(err => console.error("Profile Live Sync Error:", err));
  }, [loggedInUsername, loggedInName]);

  const displayNameStr = liveProfile ? liveProfile.name : (loggedInName || 'Student');
  const displayGradeStr = liveProfile ? liveProfile.grade : (grade || 'Grade 8');
  const displaySubjectsStr = liveProfile ? liveProfile.subjects : (subjects || '');
  
  const mySubjects = displaySubjectsStr ? displaySubjectsStr.split(', ') : [];

  useEffect(() => {
    if (!displayGradeStr) return;

    // 1. නිබන්ධන කියවීම සහ ෆිල්ටර් කිරීම
    axiosDirect.get('http://localhost:8082/api/learning-materials')
      .then(res => {
        const allMaterials = Array.isArray(res.data) ? res.data : [];
        const filtered = allMaterials.filter(m => 
          String(m.grade).toLowerCase() === String(displayGradeStr).toLowerCase() &&
          mySubjects.some(sub => m.subject && m.subject.toLowerCase() === sub.toLowerCase())
        );
        setMaterials(filtered);
      })
      .catch(err => console.error("Materials Fetch Error:", err));

    // 2. ප්‍රශ්න පත්‍ර කියවීම සහ ෆිල්ටර් කිරීම
    axiosDirect.get('http://localhost:8082/api/quizzes')
      .then(res => {
        const allQuizzes = Array.isArray(res.data) ? res.data : [];
        const filtered = allQuizzes.filter(q => 
          String(q.grade).toLowerCase() === String(displayGradeStr).toLowerCase() &&
          (q.is_enabled === 1 || q.is_enabled === true) &&
          mySubjects.some(sub => q.subject_name && q.subject_name.toLowerCase() === sub.toLowerCase())
        );
        setQuizzes(filtered);
      })
      .catch(err => console.error("Quizzes Fetch Error:", err));
  }, [displayGradeStr, displaySubjectsStr]);

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      
      {/* LEFT SIDEBAR UI */}
      <div style={styles.sidebar}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
          <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
          <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>STUDENT PORTAL</p>
        </div>
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px' }}>
          <button onClick={() => setActiveTab('dashboard')} style={styles.sidebarBtn(activeTab === 'dashboard')}>🏠 Dashboard Overview</button>
          <button onClick={() => setActiveTab('materials')} style={styles.sidebarBtn(activeTab === 'materials')}>📚 My Learning Materials ({materials.length})</button>
          <button onClick={() => setActiveTab('exams')} style={styles.sidebarBtn(activeTab === 'exams')}>📝 My Online Exams ({quizzes.length})</button>
          <button onClick={() => setActiveTab('forum')} style={styles.sidebarBtn(activeTab === 'forum')}>💬 Class Forum Space</button>
          <button onClick={() => setActiveTab('profile')} style={styles.sidebarBtn(activeTab === 'profile')}>👤 Profile Identity</button>
        </div>

        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}>
          <button onClick={handleLogout} style={styles.logoutBtn}>🚪 Logout Portal</button>
        </div>
      </div>

      {/* MAIN WORKSPACE CORE AREA */}
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        {activeTab === 'dashboard' && (
          <div style={{ animation: 'fadeIn 0.5s', display: 'flex', flexDirection: 'column', gap: '25px' }}>
            
            {/* GREEN WELCOME ACCENT BANNER */}
            <div style={styles.welcomeBanner}>
              <h1 style={{ margin: '0 0 8px 0', fontSize: '26px' }}>Welcome back, {displayNameStr}! 🎓</h1>
              <p style={{ margin: 0, opacity: 0.9, fontSize: '14px' }}>Access your online classrooms, download handouts, and join live quizzes instantly.</p>
            </div>

            {/* DYNAMIC COUNT STATS GRID */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '20px' }}>
              <div style={styles.statCard('#7c3aed')}>
                <div>
                  <p style={styles.statLabel}>My Registered Grade</p>
                  <h2 style={styles.statValue}>{displayGradeStr}</h2>
                </div>
                <div style={styles.statIcon}>🏫</div>
              </div>

              <div style={styles.statCard('#2563eb')}>
                <div>
                  <p style={styles.statLabel}>Available Handouts</p>
                  <h2 style={styles.statValue}>{materials.length} Materials</h2>
                </div>
                <div style={styles.statIcon}>📂</div>
              </div>

              <div style={styles.statCard('#ea580c')}>
                <div>
                  <p style={styles.statLabel}>Pending Quizzes</p>
                  <h2 style={styles.statValue}>{quizzes.length} Papers</h2>
                </div>
                <div style={styles.statIcon}>✏️</div>
              </div>
            </div>

            <h3 style={{ color: '#1e293b', margin: '15px 0 0 0', fontSize: '18px' }}>
              🏫 My Classrooms ({displayGradeStr} / Enrolled Subjects)
            </h3>

            {/* MAPPED CLASSROOMS MATRIX */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '20px' }}>
              {mySubjects.map((sub, idx) => (
                <div key={idx} style={styles.classCard}>
                  <div style={{ fontWeight: 'bold', color: '#1e293b', fontSize: '15px' }}>{displayGradeStr} - {sub}</div>
                  <div style={{ fontSize: '12px', color: '#16a34a', marginTop: '8px', fontWeight: 'bold', backgroundColor: '#dcfce7', display: 'inline-block', padding: '3px 8px', borderRadius: '4px' }}>
                    🟢 Active & Mapped
                  </div>
                </div>
              ))}
              {mySubjects.length === 0 && (
                <p style={{ color: '#94a3b8', fontStyle: 'italic', padding: '10px' }}>📭 විෂයන් කියවෙමින් පවතී හෝ ඇතුළත් කර නොමැත.</p>
              )}
            </div>

          </div>
        )}

        {/* MATERIALS MODULE TAB */}
        {activeTab === 'materials' && (
          <div>
            <h3>📚 Enrolled Materials Archive ({materials.length})</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '15px' }}>
              {materials.map((m, i) => (
                <div key={i} style={{ backgroundColor: 'white', padding: '16px 20px', borderRadius: '12px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center', boxShadow: '0 2px 8px rgba(0,0,0,0.01)' }}>
                  <div>
                    <h5 style={{ margin: 0, fontSize: '14.5px', color: '#1e293b', fontWeight: '600' }}>{m.title}</h5>
                    <span style={{ fontSize: '11.5px', color: '#64748b', fontWeight: 'bold', backgroundColor: '#f1f5f9', padding: '2px 6px', borderRadius: '4px', marginTop: '4px', display: 'inline-block' }}>
                      {m.subject} {m.material_type ? `| ${m.material_type}` : ''}
                    </span>
                  </div>
                  
                  {/* 🟢 FIXED ACTIONS BUTTON GRID: View සහ Download බොත්තම් දෙකම එකතු කර ඇත */}
                  <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
                    <button 
                      onClick={() => setPreviewMaterial(m)} 
                      style={{ backgroundColor: '#16a34a', color: 'white', padding: '7px 14px', borderRadius: '6px', border: 'none', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '5px' }}
                    >
                      👁️ View In-App
                    </button>
                    <a 
                      href={`http://localhost:8082/${m.file_path}`} 
                      target="_blank" 
                      rel="noreferrer" 
                      style={{ backgroundColor: '#2563eb', color: 'white', padding: '7px 14px', borderRadius: '6px', textDecoration: 'none', fontSize: '12px', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '5px' }}
                    >
                      📥 Download
                    </a>
                  </div>
                </div>
              ))}
              {materials.length === 0 && <p style={{ color: '#94a3b8', fontStyle: 'italic' }}>ඔබට අදාළ නිබන්ධන කිසිවක් නැත.</p>}
            </div>
          </div>
        )}

        {activeTab === 'exams' && (
          <div>
            <h3>📝 Available Online Examinations ({quizzes.length})</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '15px' }}>
              {quizzes.map((q, i) => (
                <div key={i} style={{ backgroundColor: 'white', padding: '15px', borderRadius: '10px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <h5 style={{ margin: 0, fontSize: '14px', color: '#1e293b' }}>{q.title}</h5>
                    <span style={{ fontSize: '11px', color: '#64748b' }}>Subject: {q.subject_name}</span>
                  </div>
                  <button style={{ backgroundColor: '#16a34a', color: 'white', border: 'none', padding: '6px 14px', borderRadius: '6px', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer' }}>🚀 Attempt Quiz</button>
                </div>
              ))}
              {quizzes.length === 0 && <p style={{ color: '#94a3b8', fontStyle: 'italic' }}>දැනට පවත්වන සක්‍රීය විභාග කිසිවක් නැත.</p>}
            </div>
          </div>
        )}

        {activeTab !== 'dashboard' && activeTab !== 'materials' && activeTab !== 'exams' && (
          <div style={{ color: '#64748b', fontStyle: 'italic' }}>🔒 Section operational structures loaded inside root gateway.</div>
        )}
      </div>

      {/* 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢
          --- DYNAMIC CENTRAL LESSON INTERACTIVE PREVIEW MODAL ---
          🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 🟢 */}
      {previewMaterial && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            
            {/* Modal Navigation Header Header */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px', borderBottom: '2px solid #e2e8f0', paddingBottom: '12px' }}>
              <div>
                <h4 style={{ margin: 0, color: '#1e293b', fontSize: '16px', fontWeight: 'bold' }}>
                  📖 Smart Lesson View: {previewMaterial.title}
                </h4>
                <span style={{ fontSize: '11px', color: '#64748b', fontWeight: '500' }}>
                  Target Mapped Node: {previewMaterial.subject} | {previewMaterial.grade}
                </span>
              </div>
              <button 
                onClick={() => setPreviewMaterial(null)} 
                style={{ background: '#fee2e2', border: 'none', fontSize: '14px', cursor: 'pointer', color: '#b91c1c', padding: '5px 10px', borderRadius: '6px', fontWeight: 'bold' }}
              >
                ✕ Close Viewer
              </button>
            </div>

            {/* Core Interactive Media Rendering Frame Block */}
            <div style={{ backgroundColor: '#f1f5f9', padding: '8px', borderRadius: '10px', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
              {String(previewMaterial.file_path).toLowerCase().endsWith('.mp4') || 
               String(previewMaterial.material_type).toLowerCase().includes('video') ? (
                // 🎬 CASE A: වීඩියෝ පාඩමක් නම් Live Video Player එකක් පෙන්වයි
                <video 
                  src={`http://localhost:8082/${previewMaterial.file_path}`} 
                  controls 
                  controlsList="nodownload"
                  autoPlay
                  style={{ width: '100%', maxHeight: '460px', borderRadius: '8px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)' }} 
                />
              ) : (
                // 📄 CASE B: PDF හෝ Document එකක් නම් Live Document Embed Canvas එකක් පෙන්වයි
                <iframe 
                  src={`http://localhost:8082/${previewMaterial.file_path}#toolbar=0`} 
                  title="AuraPen Advanced Document Canvas Viewer" 
                  style={{ width: '100%', height: '490px', border: 'none', borderRadius: '8px', backgroundColor: 'white' }} 
                />
              )}
            </div>
            
          </div>
        </div>
      )}

    </div>
  );
}

